// Convert form fields into the same shape the webhook delivers ({ body: {...} })
return $input.all().map(item => {
  const f = item.json;
  return { json: { body: {
    bench_id: f['Bench ID'],
    step_id: String(f['Step'] || '').slice(0, 3),
    status: f['Status'],
    technician: f['Technician'],
    comment: f['Comment'] || '',
    source: 'form',
  } } };
});

const STEPS = {
  S01: 'Mechanical installation & wiring check',
  S02: 'Power-up & safety circuit (E-Stop) test',
  S03: 'Network / CAN communication check',
  S04: 'Sensor & actuator calibration',
  S05: 'Software flashing & HIL configuration',
  S06: 'Reference test run',
  S07: 'Documentation & release / handover',
};
const ALLOWED = ['PASS', 'FAIL', 'BLOCKED', 'IN_PROGRESS'];

return $input.all().map(item => {
  const b = item.json.body || {};
  const errors = [];
  if (!b.bench_id) errors.push('bench_id is required');
  if (!STEPS[b.step_id]) errors.push(`step_id must be one of ${Object.keys(STEPS).join(', ')}`);
  const status = String(b.status || '').toUpperCase();
  if (!ALLOWED.includes(status)) errors.push(`status must be one of ${ALLOWED.join(', ')}`);
  if (!b.technician) errors.push('technician is required');

  return {
    json: {
      valid: errors.length === 0,
      errors,
      record: {
        bench_id: String(b.bench_id || '').trim().toUpperCase(),
        step_id: b.step_id,
        step_name: STEPS[b.step_id] || null,
        status,
        technician: b.technician || null,
        comment: b.comment || '',
        measurements: b.measurements || {},
        timestamp: new Date().toISOString(),
        total_steps: Object.keys(STEPS).length,
      },
    },
  };
});

// Simple persistence for the demo: workflow static data (only saved for
// production executions, i.e. when the workflow is active).
// In a real setup replace this with SharePoint / Microsoft Lists / Postgres.
const db = $getWorkflowStaticData('global');
db.benches = db.benches || {};
db.log = db.log || [];

return $input.all().map(item => {
  const r = item.json.record;
  const bench = db.benches[r.bench_id] = db.benches[r.bench_id] || { steps: {}, created_at: r.timestamp };
  bench.steps[r.step_id] = {
    status: r.status, step_name: r.step_name, technician: r.technician,
    comment: r.comment, timestamp: r.timestamp,
  };
  bench.updated_at = r.timestamp;

  db.log.push(r);
  if (db.log.length > 500) db.log.shift();

  const passed = Object.values(bench.steps).filter(s => s.status === 'PASS').length;
  const progress_pct = Math.round((passed / r.total_steps) * 100);
  return { json: { ...r, progress_pct, release_ready: passed === r.total_steps } };
});

return $input.all().map(item => {
  const r = item.json;
  const text =
    `⚠️ Commissioning issue on ${r.bench_id}\n` +
    `Step ${r.step_id} – ${r.step_name}: ${r.status}\n` +
    `Technician: ${r.technician}\n` +
    (r.comment ? `Comment: ${r.comment}\n` : '') +
    `Bench progress: ${r.progress_pct}%`;
  return { json: { channel: 'commissioning-alerts', text, ...r } };
});

const STEPS = {
  S01: 'Mechanical installation & wiring check',
  S02: 'Power-up & safety circuit (E-Stop) test',
  S03: 'Network / CAN communication check',
  S04: 'Sensor & actuator calibration',
  S05: 'Software flashing & HIL configuration',
  S06: 'Reference test run',
  S07: 'Documentation & release / handover',
};
const db = $getWorkflowStaticData('global');
const benches = db.benches || {};
const ids = Object.keys(STEPS);
const color = { PASS: '#2e7d32', FAIL: '#c62828', BLOCKED: '#ef6c00', IN_PROGRESS: '#1565c0' };

const rows = Object.entries(benches).sort().map(([id, b]) => {
  const passed = ids.filter(s => b.steps[s]?.status === 'PASS').length;
  const pct = Math.round((passed / ids.length) * 100);
  const cells = ids.map(s => {
    const st = b.steps[s];
    if (!st) return '<td style="color:#999">—</td>';
    return `<td title="${st.technician} @ ${st.timestamp}" style="color:#fff;background:${color[st.status]}">${st.status}</td>`;
  }).join('');
  const release = pct === 100 ? '✅ Ready' : 'Open';
  return `<tr><th>${id}</th>${cells}<td>${pct}%</td><td>${release}</td><td>${b.updated_at}</td></tr>`;
}).join('');

const head = ids.map(s => `<th title="${STEPS[s]}">${s}</th>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><title>Commissioning Status</title>
<style>body{font-family:system-ui;margin:24px}table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:6px 10px;text-align:center;font-size:13px}</style></head>
<body><h2>Test Bench Commissioning – Live Status</h2>
<table><tr><th>Bench</th>${head}<th>Progress</th><th>Release</th><th>Last update</th></tr>
${rows || '<tr><td colspan="11">No data yet</td></tr>'}</table>
<p style="color:#666;font-size:12px">${ids.map(s => s + ' = ' + STEPS[s]).join(' · ')}</p></body></html>`;

return [{ json: { html } }];

const STEPS = {
  S01: 'Mechanical installation & wiring check',
  S02: 'Power-up & safety circuit (E-Stop) test',
  S03: 'Network / CAN communication check',
  S04: 'Sensor & actuator calibration',
  S05: 'Software flashing & HIL configuration',
  S06: 'Reference test run',
  S07: 'Documentation & release / handover',
};
const db = $getWorkflowStaticData('global');
const benches = db.benches || {};
const total = Object.keys(STEPS).length;
const lines = [];
let ready = 0;

for (const [id, b] of Object.entries(benches).sort()) {
  const steps = Object.values(b.steps);
  const passed = steps.filter(s => s.status === 'PASS').length;
  const issues = Object.entries(b.steps)
    .filter(([, s]) => s.status === 'FAIL' || s.status === 'BLOCKED')
    .map(([k, s]) => `${k} ${s.status}`);
  if (passed === total) ready++;
  lines.push(`${id}: ${passed}/${total} steps passed` + (issues.length ? ` | open issues: ${issues.join(', ')}` : ''));
}

const subject = `Daily commissioning status – ${new Date().toISOString().slice(0, 10)}`;
const body = [`Benches tracked: ${Object.keys(benches).length}`, `Release-ready: ${ready}`, '', ...lines].join('\n');
return [{ json: { subject, body } }];
